--
-- Name: view_ai_students; Type: VIEW; Schema: yuxiao; Owner: yuxiao
--

CREATE VIEW view_ai_students("S#","SNAME","GRADE") AS
    SELECT s."S#", s."SNAME", sc."GRADE" FROM (("S935" s JOIN "SC935" sc ON (((s."S#")::text = (sc."S#")::text))) JOIN "C935" c ON (((sc."C#")::text = (c."C#")::text))) WHERE ((c."CNAME")::text = '人工智能'::text);


ALTER VIEW yuxiao.view_ai_students OWNER TO yuxiao;

--
-- Name: view_dong18_male; Type: VIEW; Schema: yuxiao; Owner: yuxiao
--

CREATE VIEW view_dong18_male("S#","SNAME","BDATE","HEIGHT") AS
    SELECT "S935"."S#", "S935"."SNAME", "S935"."BDATE", "S935"."HEIGHT" FROM "S935" WHERE ((("S935"."DORM")::text ~~ '东18舍%'::text) AND (("S935"."SEX")::text = '男'::text));


ALTER VIEW yuxiao.view_dong18_male OWNER TO yuxiao;

--
-- Name: view_zhangming_courses; Type: VIEW; Schema: yuxiao; Owner: yuxiao
--

CREATE VIEW view_zhangming_courses("C#","CNAME",avg_grade) AS
    SELECT c."C#", c."CNAME", avg(sc."GRADE") AS avg_grade FROM ("C935" c LEFT JOIN "SC935" sc ON (((c."C#")::text = (sc."C#")::text))) WHERE (((c."TEACHER")::text = '张明'::text) AND ((c."C#")::text = 'EE-01'::text)) GROUP BY c."C#", c."CNAME";


ALTER VIEW yuxiao.view_zhangming_courses OWNER TO yuxiao;

